  difficulty: Difficulty,
  limit: number = 100,
  characterType?: string
): Promise<LeaderboardResponse> {
  const cacheKey = `${difficulty}:${limit}:${characterType ?? ''}`;
  const cached = _lbCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < _LB_TTL) {
